fn argmax(a: Vec<i8>) -> usize {
    // Problem statement guarantees non-empty input.
    let mut best_idx: usize = 0;
    let mut best_val: i8 = a[0];

    for (i, &v) in a.iter().enumerate().skip(1) {
        if v > best_val {
            best_val = v;
            best_idx = i;
        }
        // If v == best_val, do nothing to keep the earliest index.
    }

    best_idx
}

fn main() {
    // Simple sanity checks
    assert_eq!(argmax(vec![1i8]), 0);
    assert_eq!(argmax(vec![-5, -2, -2, -9]), 1); // tie -> earliest
    assert_eq!(argmax(vec![3, 7, 7, 1]), 1);     // tie -> earliest
    assert_eq!(argmax(vec![-128, 127, 0]), 1);

    println!("OK");
}